  package   de . uni_koblenz . jgralab ;   public enum EdgeDirection  {  IN ,  OUT ,  INOUT  ;   public static EdgeDirection parse  (  String direction )  throws Exception  {  if  (  direction . equals  ( "OUT" ) )  {  return  EdgeDirection . OUT ; } else  if  (  direction . equals  ( "IN" ) )  {  return  EdgeDirection . IN ; } else  if  (  direction . equals  ( "INOUT" ) )  {  return  EdgeDirection . INOUT ; } else  {  throw  new Exception  ( "Could not determine direction from string." ) ; } } }